public async Task ControlPlayback(IMediaPlayerControls player, string mediaPath)
{
    if (await player.OpenAsync(mediaPath))
    {
        await player.PlayAsync();
        await Task.Delay(5000); // Play for 5 seconds

        await player.PauseAsync();
        await Task.Delay(2000);

        player.Position_Set(TimeSpan.FromMinutes(1));
        await player.ResumeAsync();
    }
}

// Assuming 'videoCapture' is an object that implements IStatusOverlay.
public void ConfigureStatusOverlay(IVideoCapture videoCapture)
{
    // To use the status overlay, you would typically cast the object to the interface.
    IStatusOverlay statusOverlay = videoCapture as IStatusOverlay;
